import{_t as e,it as t,n,rt as r}from"./chunks/framework.wyZghjns.js";var i=JSON.parse(`{"title":"Class: RemoteLogTransport","description":"","frontmatter":{},"headers":[],"relativePath":"api/@jsprismarine/prismarine/classes/RemoteLogTransport.md","filePath":"api/@jsprismarine/prismarine/classes/RemoteLogTransport.md"}`),a={name:`api/@jsprismarine/prismarine/classes/RemoteLogTransport.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p><a href="./../../../">JSPrismarine</a> / <a href="./../">@jsprismarine/prismarine</a> / RemoteLogTransport</p><h1 id="class-remotelogtransport" tabindex="-1">Class: RemoteLogTransport <a class="header-anchor" href="#class-remotelogtransport" aria-label="Permalink to “Class: RemoteLogTransport”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/bb5fe75d768a8b313bb0ef2add190afe2ec9d855/packages/prismarine/src/console/RemoteLogTransport.ts#L40" target="_blank" rel="noreferrer">packages/prismarine/src/console/RemoteLogTransport.ts:40</a></p><p>Forwards log records to the console process as <code>log</code> messages.</p><p>Every record the logger emits at or above the subscribed level becomes one message with a <code>seq</code> that increases by one, so the console can detect a gap. While the link reports a pause (<code>send</code> returned <code>false</code>) records queue up to the capacity; the oldest fall off and are counted. Once the link drains, a single <code>log.dropped</code> with that count goes out before the queued records resume, so the console knows where the hole is.</p><p>When the link closes under the transport, the queue is dropped and the retry stops; there is no one left to deliver to, and <a href="#close">close</a> then sends nothing.</p><h2 id="implements" tabindex="-1">Implements <a class="header-anchor" href="#implements" aria-label="Permalink to “Implements”">​</a></h2><ul><li><a href="./../../logger/interfaces/LogTransport.html"><code>LogTransport</code></a></li></ul><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new RemoteLogTransport</strong>(<code>link</code>, <code>options?</code>): <code>RemoteLogTransport</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/bb5fe75d768a8b313bb0ef2add190afe2ec9d855/packages/prismarine/src/console/RemoteLogTransport.ts#L56" target="_blank" rel="noreferrer">packages/prismarine/src/console/RemoteLogTransport.ts:56</a></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="link" tabindex="-1">link <a class="header-anchor" href="#link" aria-label="Permalink to “link”">​</a></h5><p><a href="./../type-aliases/FlushableLink.html"><code>FlushableLink</code></a>&lt;<a href="./../../console-protocol/type-aliases/ConsoleMessage.html"><code>ConsoleMessage</code></a>, <a href="./../../console-protocol/type-aliases/ServerMessage.html"><code>ServerMessage</code></a>&gt;</p><p>The server end of the console link.</p><h5 id="options" tabindex="-1">options? <a class="header-anchor" href="#options" aria-label="Permalink to “options?”">​</a></h5><p><a href="./../interfaces/RemoteLogTransportOptions.html"><code>RemoteLogTransportOptions</code></a> = <code>{}</code></p><p>Queue capacity and retry delay.</p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>RemoteLogTransport</code></p><h2 id="accessors" tabindex="-1">Accessors <a class="header-anchor" href="#accessors" aria-label="Permalink to “Accessors”">​</a></h2><h3 id="dropped" tabindex="-1">dropped <a class="header-anchor" href="#dropped" aria-label="Permalink to “dropped”">​</a></h3><h4 id="get-signature" tabindex="-1">Get Signature <a class="header-anchor" href="#get-signature" aria-label="Permalink to “Get Signature”">​</a></h4><blockquote><p><strong>get</strong> <strong>dropped</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/bb5fe75d768a8b313bb0ef2add190afe2ec9d855/packages/prismarine/src/console/RemoteLogTransport.ts#L66" target="_blank" rel="noreferrer">packages/prismarine/src/console/RemoteLogTransport.ts:66</a></p><p>Records dropped from the queue and not yet announced with a <code>log.dropped</code> message.</p><h5 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h5><p><code>number</code></p><hr><h3 id="pending" tabindex="-1">pending <a class="header-anchor" href="#pending" aria-label="Permalink to “pending”">​</a></h3><h4 id="get-signature-1" tabindex="-1">Get Signature <a class="header-anchor" href="#get-signature-1" aria-label="Permalink to “Get Signature”">​</a></h4><blockquote><p><strong>get</strong> <strong>pending</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/bb5fe75d768a8b313bb0ef2add190afe2ec9d855/packages/prismarine/src/console/RemoteLogTransport.ts#L71" target="_blank" rel="noreferrer">packages/prismarine/src/console/RemoteLogTransport.ts:71</a></p><p>Records waiting for the link to drain.</p><h5 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h5><p><code>number</code></p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="close" tabindex="-1">close() <a class="header-anchor" href="#close" aria-label="Permalink to “close()”">​</a></h3><blockquote><p><strong>close</strong>(): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/bb5fe75d768a8b313bb0ef2add190afe2ec9d855/packages/prismarine/src/console/RemoteLogTransport.ts#L115" target="_blank" rel="noreferrer">packages/prismarine/src/console/RemoteLogTransport.ts:115</a></p><p>Hands every queued record to the link at once, with the pending <code>log.dropped</code> first, and stops accepting records. The link queues them itself even while it reports a pause, so nothing here is lost; whether they reach the other end before the process exits is up to the link&#39;s <code>flush</code>.</p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><h4 id="implementation-of" tabindex="-1">Implementation of <a class="header-anchor" href="#implementation-of" aria-label="Permalink to “Implementation of”">​</a></h4><p><a href="./../../logger/interfaces/LogTransport.html"><code>LogTransport</code></a>.<a href="./../../logger/interfaces/LogTransport.html#close"><code>close</code></a></p><hr><h3 id="log" tabindex="-1">log() <a class="header-anchor" href="#log" aria-label="Permalink to “log()”">​</a></h3><blockquote><p><strong>log</strong>(<code>record</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/bb5fe75d768a8b313bb0ef2add190afe2ec9d855/packages/prismarine/src/console/RemoteLogTransport.ts#L87" target="_blank" rel="noreferrer">packages/prismarine/src/console/RemoteLogTransport.ts:87</a></p><p>Forwards the record, or queues it while the link is paused. Records logged after <a href="#close">close</a> are ignored.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="record" tabindex="-1">record <a class="header-anchor" href="#record" aria-label="Permalink to “record”">​</a></h5><p><a href="./../../logger/interfaces/LogRecord.html"><code>LogRecord</code></a></p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><h4 id="implementation-of-1" tabindex="-1">Implementation of <a class="header-anchor" href="#implementation-of-1" aria-label="Permalink to “Implementation of”">​</a></h4><p><a href="./../../logger/interfaces/LogTransport.html"><code>LogTransport</code></a>.<a href="./../../logger/interfaces/LogTransport.html#log"><code>log</code></a></p><hr><h3 id="setlevel" tabindex="-1">setLevel() <a class="header-anchor" href="#setlevel" aria-label="Permalink to “setLevel()”">​</a></h3><blockquote><p><strong>setLevel</strong>(<code>level</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/bb5fe75d768a8b313bb0ef2add190afe2ec9d855/packages/prismarine/src/console/RemoteLogTransport.ts#L79" target="_blank" rel="noreferrer">packages/prismarine/src/console/RemoteLogTransport.ts:79</a></p><p>Sets the least severe level still forwarded. Records below it are skipped and consume no <code>seq</code>. Defaults to <code>silly</code>, which forwards everything the logger emits.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="level" tabindex="-1">level <a class="header-anchor" href="#level" aria-label="Permalink to “level”">​</a></h5><p><code>&quot;warn&quot;</code> | <code>&quot;error&quot;</code> | <code>&quot;info&quot;</code> | <code>&quot;verbose&quot;</code> | <code>&quot;debug&quot;</code> | <code>&quot;silly&quot;</code></p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p>`,68)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};